 SELECT * INTO STRICT current_listing FROM zoi.listings WHERE id=(p->>'listing_id')::uuid FOR UPDATE;
 IF md5(to_jsonb(current_listing)::text) IS DISTINCT FROM p->>'expected_full_row_fingerprint' OR zoi.listing_quality_fingerprint(current_listing) IS DISTINCT FROM p->>'quality_fingerprint' OR zoi.enrich_authority_fingerprint(current_listing) IS DISTINCT FROM p->>'authority_fingerprint' OR current_listing.owner_user_id IS NOT NULL OR current_listing.owner_workspace_id IS NOT NULL OR current_listing.claim_status IS DISTINCT FROM 'unclaimed' OR current_listing.publish_status IS DISTINCT FROM 'published' OR current_listing.moderation_status NOT IN('clean','cleared') OR coalesce(current_listing.marketplace_status,'')='hidden' OR current_listing.profile#>'{_enrich,lease}' IS NOT NULL OR EXISTS(SELECT 1 FROM zoi.home_designs d WHERE d.listing_id=current_listing.id) THEN RAISE EXCEPTION 'reviewed_lunch_current_context_changed';END IF;
 current_context:=jsonb_build_object('listing_id',current_listing.id,'name',current_listing.name,'entity_type',current_listing.entity_type,'website',current_listing.website,'address',current_listing.address,'city',current_listing.city,'country',current_listing.country,'category_slug',(SELECT slug FROM zoi.categories WHERE id=current_listing.primary_category_id),'primary_category_id',current_listing.primary_category_id,'owner_user_id',current_listing.owner_user_id,'owner_workspace_id',current_listing.owner_workspace_id,'claim_status',current_listing.claim_status);
 IF current_context IS DISTINCT FROM p#>'{profile,source_identity,canonical_context}' OR p#>>'{profile,source_identity,verification}' IS DISTINCT FROM 'reviewed_official_visible_branch' OR p#>>'{profile,food_source_coverage,menu_kind}' IS DISTINCT FROM 'lunch' OR p#>>'{profile,food_source_coverage,entire_business_offering}' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'reviewed_lunch_scope_changed';END IF;
 FOR k IN SELECT jsonb_object_keys(p->'profile') LOOP IF current_listing.profile?k THEN RAISE EXCEPTION 'reviewed_lunch_authored_field_present:%',k;END IF;END LOOP;
 before_row:=to_jsonb(current_listing);
 SELECT * INTO STRICT lease FROM public.enrich_sample_lease(ARRAY[current_listing.id]);
 IF lease.listing_id IS DISTINCT FROM current_listing.id OR lease.name IS DISTINCT FROM current_listing.name OR lease.website IS DISTINCT FROM current_listing.website OR lease.entity_type IS DISTINCT FROM current_listing.entity_type OR lease.slug IS DISTINCT FROM current_listing.slug OR lease.owner_managed IS DISTINCT FROM false OR lease.owner_workspace_id IS NOT NULL OR lease.existing_enrich IS DISTINCT FROM ((coalesce(current_listing.profile->'_enrich','{}')-'lease')||jsonb_build_object('_lease_source_context',jsonb_build_object('city',current_listing.city,'country',current_listing.country,'address',current_listing.address))) THEN RAISE EXCEPTION 'reviewed_lunch_canonical_lease_changed';END IF;
 SELECT l.profile#>'{_enrich,lease}' INTO STRICT stored_lease FROM zoi.listings l WHERE l.id=current_listing.id;
 IF stored_lease->>'id' IS DISTINCT FROM lease.lease_id OR stored_lease->>'task' IS DISTINCT FROM 'enrichment' OR stored_lease->>'fingerprint' IS DISTINCT FROM p->>'quality_fingerprint' OR stored_lease->>'source_website' IS DISTINCT FROM current_listing.website OR stored_lease->>'authority_version' IS DISTINCT FROM '1' OR stored_lease->>'authority_fingerprint' IS DISTINCT FROM p->>'authority_fingerprint' OR (zoi.enrich_timestamp(stored_lease->>'expires_at')>clock_timestamp()) IS DISTINCT FROM true THEN RAISE EXCEPTION 'reviewed_lunch_stored_lease_changed';END IF;
 SELECT * INTO STRICT ack FROM public.enrich_apply(jsonb_build_array(jsonb_build_object('slug',current_listing.slug,'website',current_listing.website,'lease_id',lease.lease_id,'profile',p->'profile','provenance',p->'provenance')));
 IF ack.slug IS DISTINCT FROM current_listing.slug OR ack.applied IS DISTINCT FROM true THEN RAISE EXCEPTION 'reviewed_lunch_apply_unconfirmed';END IF;
 SELECT * INTO STRICT current_listing FROM zoi.listings WHERE id=(p->>'listing_id')::uuid;
 IF (to_jsonb(current_listing)-ARRAY['profile','updated_at']) IS DISTINCT FROM (before_row-ARRAY['profile','updated_at']) OR (current_listing.profile-ARRAY['_enrich','_coverage']) IS DISTINCT FROM ((before_row->'profile')-ARRAY['_enrich','_coverage']) OR current_listing.profile#>'{_enrich,menu}' IS DISTINCT FROM p#>'{profile,menu}' OR ARRAY(SELECT jsonb_array_length(s->'items')FROM jsonb_array_elements(current_listing.profile#>'{_enrich,menu}')s) IS DISTINCT FROM ARRAY[17] OR current_listing.profile#>>'{_enrich,menu_total_items}' IS DISTINCT FROM '17' OR current_listing.profile#>>'{_enrich,menu_truncated}' IS DISTINCT FROM 'false' OR current_listing.profile#>'{_enrich,lease}' IS NOT NULL OR current_listing.profile#>'{_enrich,_lease_source_context}' IS NOT NULL THEN RAISE EXCEPTION 'reviewed_lunch_protected_readback_changed';END IF;
 FOR k,v IN SELECT key,value FROM jsonb_each(p->'profile') LOOP IF k NOT IN('checked_at','last_attempt_at','status')AND current_listing.profile->'_enrich'->k IS DISTINCT FROM v THEN RAISE EXCEPTION 'reviewed_lunch_payload_readback_changed:%',k;END IF;END LOOP;
 IF (zoi.reviewed_food_public_context(current_listing)->>'current') IS DISTINCT FROM 'true' OR (public.home_entity(current_listing.slug)->>'reviewed_food_receipt_current') IS DISTINCT FROM 'true' OR public.home_entity(current_listing.slug)#>'{profile,_enrich,menu}' IS DISTINCT FROM p#>'{profile,menu}' THEN RAISE EXCEPTION 'reviewed_lunch_public_receipt_unconfirmed';END IF;
 INSERT INTO three_kretans_lunch_result VALUES(jsonb_build_object('listing_id',current_listing.id,'canonical_applied',true,'menu_items',17,'scope','Lunch menu','entire_business_offering',false,'before_fingerprint',p->>'expected_full_row_fingerprint','after_fingerprint',md5(to_jsonb(current_listing)::text),'owner_raw_coordinates_unchanged',true,'public_receipt_current',true,'report_sha256',p->>'report_sha256'));
END $apply$;
COMMIT;SELECT proof||jsonb_build_object('committed',true)AS result FROM three_kretans_lunch_result;
